const textContent = `📅 REPORTE DIARIO DE CITAS\n\nEstimados Sres. ${negocioNombre},\n\nDesde AutomatizaTech le informamos que no hay citas programadas para hoy ${fechaLegible}.\n\n💡 ¡Buen momento para promocionar tus servicios!`;

return [{ 
  json: { 
    htmlContent,
    textContent,
    subject: `📅 Sin citas hoy ${fechaLegible} - ${negocioNombre}`,
    negocioEmail: data.negocioEmail
  } 
